%% Discounted IRL for linear quadratic tracking (LQT)
% Comprehensive exercise, Q2 (d). Plant xdot = A x + B u, reference
% xd(t) = [sin t; cos t], generated by xd' = F xd with F = [0 1; -1 0].
% Following Modares and Lewis (IEEE TAC, 2014), use the augmented state
% X = [e; xd], e = x - xd:
%   X' = Ta X + B1 u,  Ta = [A, A - F; 0, F],  B1 = [B; 0]
% and the discounted cost
%   V(X(t)) = int_t^inf exp(-gamma (tau - t)) (e'Qe + u'Ru) dtau,  Q_T = blkdiag(Q, 0).
% With V = X'PX, on-policy IRL solves over intervals [t, t+T]
%   X(t)'P_j X(t) - exp(-gamma T) X(t+T)'P_j X(t+T) = int exp(-gamma (tau - t)) r dtau
% for P_j (no A or F needed), then K_{j+1} = R^-1 B1' P_j.
% The optimum solves the discounted ARE  Ta'P + P Ta - gamma P + Q_T - P B1 R^-1 B1' P = 0.
clear; close all; rng(5);

A = [0.5 1.5; 2 -2]; B = [1; 4]; F = [0 1; -1 0];
Q = eye(2); R = 3; Ta = [A, A - F; zeros(2), F]; B1 = [B; zeros(2,1)];
QT = blkdiag(Q, zeros(2)); nX = 4;
gammas = [0.4 0.9]; dt = 1e-3; T = 0.05; nInt = round(T/dt);
figure('Position', [100 100 760 560]);
for gi = 1:numel(gammas)
    gam = gammas(gi);
    [Pstar, ~, Kstar] = care(Ta - gam/2*eye(nX), B1, QT, R);   % reference solution
    K = [1 1 0 0]; err = [];                                     % stabilising initial policy
    for j = 1:20
        nEq = 60; Phi = zeros(nEq, 10); y = zeros(nEq, 1);
        X = [5; -5; 0; 1];
        for k = 1:nEq
            b0 = qb(X); c = 0; tau = 0;
            for s = 1:nInt
                u  = -K*X + 0.1*rand;                            % probing noise in [0, 0.1]
                Xn = rk4(@(z) Ta*z + B1*u, X, dt);
                r0 = X(1:2)'*Q*X(1:2) + R*u^2; r1 = Xn(1:2)'*Q*Xn(1:2) + R*u^2;
                c  = c + dt/2*(exp(-gam*tau)*r0 + exp(-gam*(tau + dt))*r1);
                X = Xn; tau = tau + dt;
            end
            Phi(k,:) = (b0 - exp(-gam*T)*qb(X))'; y(k) = c;
            if mod(k, 10) == 0, X = [5*randn(2,1); 2*randn(2,1)]; end
        end
        P = s2m(Phi \ y); Kn = R \ (B1'*P);
        err(end+1) = norm(P - Pstar); %#ok<SAGROW>
        if norm(Kn - K) < 1e-3, K = Kn; break; end
        K = Kn;
    end
    fprintf('gamma = %.1f: %d iterations, K = [%s]\n', gam, j, num2str(K, '%8.4f'));
    fprintf('             discounted ARE K* = [%s]\n', num2str(Kstar, '%8.4f'));
    % closed loop: x(0) = [5; -5], xd(0) = [0; 1]
    [tc, Xc] = ode45(@(t, z) (Ta - B1*K)*z, 0:0.01:20, [5; -5; 0; 1]);
    xs = Xc(:,1:2) + Xc(:,3:4);
    subplot(3, 2, gi); semilogy(err, '-o', 'LineWidth', 1.2); grid on;
    xlabel('Iteration j'); ylabel('$\|P_j - P^*\|$', 'Interpreter', 'latex');
    title(sprintf('\\gamma = %.1f', gam));
    subplot(3, 2, 2 + gi); plot(tc, xs(:,1), tc, Xc(:,3), '--', 'LineWidth', 1.2); grid on;
    legend('x_1', 'sin t'); xlabel('Time (s)');
    subplot(3, 2, 4 + gi); plot(tc, Xc(:,1:2), 'LineWidth', 1.2); grid on;
    legend('e_1', 'e_2'); xlabel('Time (s)'); title('Tracking error');
    fprintf('             max |e| over the last 5 s: %.3f\n', max(max(abs(Xc(tc > 15, 1:2)))));
end


% Save the figure
if ~exist('figures', 'dir'), mkdir('figures'); end
exportgraphics(gcf, fullfile('figures', 'irl_tracking.png'), 'Resolution', 150);

function b = qb(x)
% quadratic basis for a symmetric 4x4 matrix (off-diagonal terms doubled)
b = []; for i = 1:4, for jj = i:4, if i == jj, b(end+1,1) = x(i)^2; else, b(end+1,1) = 2*x(i)*x(jj); end, end, end %#ok<AGROW>
end
function P = s2m(p)
P = zeros(4); c = 0; for i = 1:4, for jj = i:4, c = c + 1; P(i,jj) = p(c); P(jj,i) = p(c); end, end
end
function x = rk4(f, x, h)
k1 = f(x); k2 = f(x + h/2*k1); k3 = f(x + h/2*k2); k4 = f(x + h*k3);
x = x + h/6*(k1 + 2*k2 + 2*k3 + k4);
end
